using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.PerfilMenuBotones;namespace GraphApi.Services.SGR.PerfilMenuBotones{    public class PerfilMenuBotonesService : IPerfilMenuBotonesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public PerfilMenuBotonesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadPerfilMenuBotones>> GetPerfilMenuBotones(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.vsPerfilMenuBotones (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadPerfilMenuBotones>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetPerfilMenuBotonesDynamic(            int? perfilMenuBotonID,            int? perfilID,            string? perfil,            int? menuBotonID,            string? boton,            string? accion,            int? menuID,            string? tituloMenu,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "PerfilMenuBotonID, PerfilID, Perfil, MenuBotonID, Boton, Accion, MenuID, TituloMenu, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.vsPerfilMenuBotones (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (perfilMenuBotonID.HasValue)            {                vSql.Append(" AND PerfilMenuBotonID = @PerfilMenuBotonID");                vParameters.Add("PerfilMenuBotonID",perfilMenuBotonID);            }            if (!string.IsNullOrWhiteSpace(perfil))            {                vSql.Append(" AND Perfil LIKE @Perfil");                vParameters.Add("Perfil",$"%{perfil}%");            }            if (!string.IsNullOrWhiteSpace(boton))            {                vSql.Append(" AND Boton LIKE @Boton");                vParameters.Add("Boton",$"%{boton}%");            }            if (!string.IsNullOrWhiteSpace(accion))            {                vSql.Append(" AND Accion LIKE @Accion");                vParameters.Add("Accion",$"%{accion}%");            }            if (!string.IsNullOrWhiteSpace(tituloMenu))            {                vSql.Append(" AND TituloMenu LIKE @TituloMenu");                vParameters.Add("TituloMenu",$"%{tituloMenu}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadPerfilMenuBotones> CreatePerfilMenuBotones(clCreatePerfilMenuBotones objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.PerfilMenuBotones                (PerfilID, MenuBotonID, bActivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@PerfilID, @MenuBotonID, @bActivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.PerfilID,                objInput.MenuBotonID,                objInput.bActivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT PerfilMenuBotonID, PerfilID, Perfil, MenuBotonID, Boton, Accion, MenuID, TituloMenu, bEliminado                FROM sgr.vsPerfilMenuBotones (NOLOCK)                WHERE PerfilMenuBotonID = @PerfilMenuBotonID;";            var vReadParams = new { PerfilMenuBotonID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadPerfilMenuBotones>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el PerfilMenuBotone con ID {vNewId}.");            return vCreated;        }        public async Task<clReadPerfilMenuBotones?> UpdatePerfilMenuBotones(clUpdatePerfilMenuBotones objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("PerfilMenuBotonID", objInput.PerfilMenuBotonID);            if (objInput.PerfilID != null)            {                vSets.Add("PerfilID = @PerfilID");                vParameters.Add("PerfilID", objInput.PerfilID);            }            if (objInput.MenuBotonID != null)            {                vSets.Add("MenuBotonID = @MenuBotonID");                vParameters.Add("MenuBotonID", objInput.MenuBotonID);            }            if (objInput.bActivo != null)            {                vSets.Add("bActivo = @bActivo");                vParameters.Add("bActivo", objInput.bActivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.PerfilMenuBotones                SET {vSetClause}                WHERE PerfilMenuBotonID = @PerfilMenuBotonID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT PerfilMenuBotonID, PerfilID, Perfil, MenuBotonID, Boton, Accion, MenuID, TituloMenu, bEliminado                FROM sgr.vsPerfilMenuBotones (NOLOCK)                WHERE PerfilMenuBotonID = @PerfilMenuBotonID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadPerfilMenuBotones>(sSelect, new {  objInput.PerfilMenuBotonID });        }        public async Task<bool> DeletePerfilMenuBotones(int nPerfilMenuBotonesID)        {            const string sSql = @"                DELETE FROM sgr.PerfilMenuBotones                WHERE PerfilMenuBotonID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nPerfilMenuBotonesID });            return vAffected > 0;        }    }}